function sql(strings, ...values) {
    let text = '';
    let collectedValues = [];
    let index = 1;
    for (let i = 0; i < strings.length; i++) {
        text += strings[i];
        if (i < values.length) {
            const val = values[i];
            if (Array.isArray(val)) {
                collectedValues.push(...val);
                text += val.map((_, idx) => `$${index + idx}`).join(', ');
                index += val.length;
            } else {
                collectedValues.push(val);
                text += `$${index++}`;
            }
        }
    }
    return { text, values: collectedValues };
}
function sql(strings, ...values) {
    let text = '';
    let valuesList = [];
    let placeholderIndex = 1;

    strings.forEach((str, i) => {
        text += str;
        if (i < values.length) {
            const val = values[i];
            if (Array.isArray(val)) {
                val.forEach((item, idx) => {
                    text += `$${placeholderIndex++}`;
                    if (idx < val.length - 1) {
                        text += ', ';
                    }
                    valuesList.push(item);
                });
            } else {
                text += `$${placeholderIndex++}`;
                valuesList.push(val);
            }
        }
    });

    return { text, values: valuesList };
}

