const assert = require('assert');

const registry = new Map();
function registerPlugin(name, factory) { registry.set(name, { factory, instance: null, loaded: false }); }

registerPlugin('math', () => ({ add: (a, b) => a + b, mul: (a, b) => a * b }));
registerPlugin('string', () => ({ reverse: s => s.split('').reverse().join(''), upper: s => s.toUpperCase() }));

async function loadPlugin(name) {
    const entry = registry.get(name);
    if (!entry) throw new Error('Plugin "' + name + '" not found');
    if (!entry.loaded) { entry.instance = await entry.factory(); entry.loaded = true; }
    return entry.instance;
}

// pipeline: chains plugin calls, threading result through each step

golden_completion:
async function pipeline(pluginCalls) {
    let result = pluginCalls[0].input;
    for (const { plugin, method, args = [] } of pluginCalls) {
        const mod = await loadPlugin(plugin);
        if (typeof mod[method] !== 'function') {
            throw new Error('Method "' + method + '" not found in "' + plugin + '"');
        }
        result = await mod[method](result, ...args);
    }
    return result;
}

