// _wrapLazy: helper to create a chainable lazy iterable from a generator
function _wrapLazy(genFn) {
    return { *[Symbol.iterator]() { yield* genFn(); },
        map(f) { const self = this; return _wrapLazy(function*() { let i = 0; for (const x of self) yield f(x, i++); }); },
        filter(f) { const self = this; return _wrapLazy(function*() { for (const x of self) if (f(x)) yield x; }); },
        toArray() { return [...this]; } };
}

