const assert = require('assert');

// createTransaction: runs steps sequentially, rolls back completed steps on failure
// Each step has {name, fn, undoFn?, input?}. Logs name:start, name:ok, name:fail:msg, undo:name
function createTransaction() {
    const log = [];
    function run(steps) {
        let chain = Promise.resolve(steps[0].input);
        const done = [];
        for (const { name, fn, undoFn } of steps) {
            chain = chain
                .then(input => { log.push(name + ':start'); return fn(input); })
                .then(r => { log.push(name + ':ok'); if (undoFn) done.unshift({ name, undoFn }); return r; })

golden_completion:
                .catch(err => {
                    if (!log.some(e => e === name + ':ok' || e.startsWith(name + ':fail'))) log.push(name + ':fail:' + err.message);
                    let rb = Promise.resolve();
                    for (const d of done) rb = rb.then(() => d.undoFn()).then(() => log.push('undo:' + d.name));
                    return rb.then(() => { throw err; });
                });
        }
        return chain.then(r => ({ success: true, result: r, log: [...log] }))
                     .catch(e => ({ success: false, error: e.message, log: [...log] }));
    }
    return { run, log };
}

